describe("services/member-service", () => {
  // can(actor, "member:update_role", …) gates the change; a member cannot self-promote.
  it("refuses a role change to an actor without member:update_role", async () => {
    const tenant = await createTenant("member-role-forbidden", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.member, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "admin",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  // The org must always retain at least one owner.
  it("refuses to demote the last remaining owner", async () => {
    const tenant = await createTenant("member-last-owner-demote", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!ownerMember) throw new Error("fixture owner missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
        role: "admin",
      }),
    ).rejects.toThrow(/at least one owner/);
  });

  // Demoting an owner is fine while another owner exists.
  it("allows demoting an owner when another owner remains", async () => {
    const tenant = await createTenant("member-second-owner", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!ownerMember || !adminMember) throw new Error("fixture member missing");

    // Promote the admin to owner first, so two owners exist.
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminMember.id,
      role: "owner",
    });

    const demoted = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: ownerMember.id,
      role: "admin",
    });

    expect(demoted.role).toBe("admin");
  });

  // member.role_changed carries both the previous and the new role.
  it("emits member.role_changed with from and to", async () => {
    const tenant = await createTenant("member-role-emit", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!target) throw new Error("fixture member missing");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.role_changed", (payload) => resolve(payload));
      void memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "member",
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      memberId: target.id,
      from: "admin",
      to: "member",
    });
  });

  // Removing the last owner is refused for the same invariant.
  it("refuses to remove the last remaining owner", async () => {
    const tenant = await createTenant("member-last-owner-remove", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!ownerMember) throw new Error("fixture owner missing");

    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
      }),
    ).rejects.toThrow(/at least one owner/);
  });

  // member.removed carries the memberId and userId that left.
  it("emits member.removed when a member is removed", async () => {
    const tenant = await createTenant("member-remove-emit", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.removed", (payload) => resolve(payload));
      void memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      memberId: target.id,
      userId: tenant.userIds.viewer,
    });
  });
});

/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}

/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
 * `issue.assigned` carries a non-null assignee by contract.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    await emit("issue.updated", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      changedFields: ["assigneeId"],
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

export async function archiveIssue(
